            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "suiteRunId": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "suite": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "files": {
                "maxItems": 100,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1024
                }
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__get_runtime_wiring",
          "description": "Project live declarative tool wiring from the admitted tool registry, manifests, provenance, and the plain host+Tool command inventory captured when the MCP server started. This is NOT a source-level call graph — use trace_path from a separately resolved handler declaration for static calls. Edges are labelled by source (manifest/provenance/registry/command-spec/host-contract) with confidence and static-bridge status. Exclusive detail modes: summary (default), groups, or nodes.",
          "score": 5.028483867645264,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 256
              },
              "command": {
                "type": "string",
                "minLength": 1,
                "maxLength": 256
              },
              "provenanceSource": {
                "type": "string",
                "enum": [
                  "bundled",
                  "installed",
                  "user-global",
                  "project-local"
                ]
              },
              "limit": {
                "default": 100,
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              },
              "cursor": {
                "type": "string",
                "minLength": 1,
                "maxLength": 4096,
                "pattern": "^[A-Za-z0-9_-]+$"
              },
              "groupBy": {
                "default": "none",
                "type": "string",
                "enum": [
                  "none",
                  "tool",
                  "source",
                  "owner"
                ]
              },
              "detail": {
                "default": "summary",
                "type": "string",
                "enum": [
                  "summary",
                  "groups",
                  "nodes"
                ]
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__refresh_graph",
          "description": "Ensure the MCP server is serving a fresh graph catalog. Auto-loads a newer catalog already persisted by `opensip graph` without rebuilding. Rebuilds only when the catalog is missing/stale, or when forceRebuild is true. EXPENSIVE when it rebuilds — do NOT loop it per query. Returns action (no-op|reloaded|rebuilt), generation, and freshness.",
          "score": 1.236488699913025,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "forceRebuild": {
                "type": "boolean"
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__compare_to_baseline",
          "description": "Use this OpenSIP MCP result tool to compare a stored fit/graph/yagni/sim run against that tool’s saved baseline. It replays the persisted session, reads stored baseline fingerprints, returns added/unchanged/resolved counts, and never re-runs the underlying tool.",
          "score": 1.2303049564361572,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "ref": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              },
              "includeResolved": {
                "type": "boolean"
              }
            },
            "required": [
              "tool"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__show_run",
          "description": "Use this OpenSIP MCP result tool first to replay an existing or prior fit/graph/yagni/sim result by id, or \"latest\" (with `tool`) for last-run, score, session, errors, warnings, or findings questions. Returns the decoded finding envelope plus session provenance and recommendedNext commands — the same filters/raw shape as `opensip sessions show`. Replays persisted sessions and never re-runs fit/graph/yagni/sim. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored-result questions.",
          "score": 1.220588207244873,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "ref": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "filters": {
                "maxItems": 16,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 64
                }
              },
              "raw": {
                "type": "boolean"
              }
            },
            "required": [
              "ref"
            ],
            "additionalProperties": false
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 54,
  "status": "ready",
  "note": null
